import * as T from './vendor/three.module.js';
import {createConveyorLibrary} from './painted-conveyor.js';import {conveyorKey,conveyorMask,changedConveyorCells} from './conveyor-connections.js';import {CARGO_ATLAS} from './painted-cargo.js';
const $=id=>document.getElementById(id),N=9;
async function start(){
const renderer=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=T.SRGBColorSpace;renderer.setClearColor(0x756f5e);renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;$('stage').prepend(renderer.domElement);
const scene=new T.Scene(),camera=new T.OrthographicCamera(),sun=new T.DirectionalLight(0xffedcc,3);sun.position.set(3,8,5);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-10,right:10,top:10,bottom:-10});sun.shadow.normalBias=.008;scene.add(sun,new T.HemisphereLight(0xfff6de,0x66685e,2));
const loader=new T.TextureLoader(),[cargo,steel]=await Promise.all([loader.loadAsync(CARGO_ATLAS),loader.loadAsync('../assets/environment/factory-machines/mill-paint-v1.png')]);for(const t of [cargo,steel])t.colorSpace=T.SRGBColorSpace;const library=createConveyorLibrary(cargo,steel),models=new T.Group();scene.add(models);
const ground=new T.Mesh(new T.PlaneGeometry(24,24),new T.MeshStandardMaterial({color:0x807762,roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.y=-.008;ground.receiveShadow=true;scene.add(ground);const grid=new T.GridHelper(9,9,0xb2a182,0x9a8f76);grid.position.y=.003;scene.add(grid);
let cells=new Set(),roots=new Map(),history=[],az=Math.PI/4,el=.65,ppu=58,focus=new T.Vector3(0,.25,0),painting=null,orbit=null,variants=false,currentPreset='route';
function render(){const w=$('stage').clientWidth,h=$('stage').clientHeight;renderer.setSize(w,h,false);camera.position.copy(focus).add(new T.Vector3(Math.sin(az)*Math.cos(el),Math.sin(el),Math.cos(az)*Math.cos(el)).multiplyScalar(20));camera.lookAt(focus);camera.updateMatrixWorld(true);ppu=+$('scale').value;if(!Number.isFinite(ppu))ppu=Math.max(12,Math.min((w-55)/13,(h-100)/9,110));camera.left=-w/ppu/2;camera.right=w/ppu/2;camera.top=h/ppu/2;camera.bottom=-h/ppu/2;camera.near=.1;camera.far=60;camera.updateProjectionMatrix();renderer.render(scene,camera);$('status').textContent=roots.size+' modules · '+Math.round(ppu)+' px/tile · '+renderer.info.render.triangles.toLocaleString()+' visible triangles';}
function sync(){for(const b of $('grid').children){const [x,y]=b.dataset.xy.split(',').map(Number);b.setAttribute('aria-pressed',String(cells.has(conveyorKey(x,y))));b.disabled=variants;} $('undo').disabled=!history.length;$('caption').textContent=variants?'All 16 neighbour combinations':'Paint a connected factory line';}
function update(x,y){const key=conveyorKey(x,y);if(roots.has(key)){models.remove(roots.get(key));roots.delete(key);}const mask=conveyorMask(cells,x,y);if(mask!==null){const root=library.build(mask);root.position.set(x-4,0,y-4);models.add(root);roots.set(key,root);} }
function rebuild(){models.clear();roots.clear();if(variants){for(let mask=0;mask<16;mask++){const root=library.build(mask);root.position.set((mask%4-1.5)*2,0,(Math.floor(mask/4)-1.5)*2);models.add(root);roots.set(String(mask),root);}}else for(const key of cells){const [x,y]=key.split(',').map(Number);update(x,y);}sync();render();}
function save(){history.push({cells:[...cells],variants,preset:currentPreset});if(history.length>50)history.shift();}
function edit(x,y,erase){if(x<0||y<0||x>=N||y>=N||variants)return;const key=conveyorKey(x,y);if(cells.has(key)===!erase)return;if(erase)cells.delete(key);else cells.add(key);for(const [a,b]of changedConveyorCells(x,y))update(a,b);sync();render();}
function stroke(x,y){if(!painting)return;const last=painting.last||[x,y],steps=Math.max(Math.abs(x-last[0]),Math.abs(y-last[1]),1);let previous=last;for(let i=1;i<=steps;i++){const next=[Math.round(last[0]+(x-last[0])*i/steps),Math.round(last[1]+(y-last[1])*i/steps)];if(next[0]!==previous[0]&&next[1]!==previous[1])edit(next[0],previous[1],painting.erase);edit(...next,painting.erase);previous=next;}painting.last=[x,y];}
function preset(name,record=true){if(record)save();currentPreset=name;variants=name==='variants';cells=new Set();const add=(x,y)=>cells.add(conveyorKey(x,y));if(name==='route'){for(let y=1;y<=6;y++)add(2,y);for(let x=2;x<=6;x++)add(x,6);for(let y=3;y<=6;y++)add(6,y);}if(name==='loop'){for(let i=1;i<=7;i++){add(i,1);add(i,7);add(1,i);add(7,i);}}if(name==='junctions'){for(let i=1;i<=7;i++){add(4,i);add(i,4);}for(let x=1;x<=4;x++)add(x,1);add(1,7);}rebuild();}
for(let y=0;y<N;y++)for(let x=0;x<N;x++){const b=document.createElement('button');b.dataset.xy=[x,y];b.setAttribute('aria-label','Conveyor column '+(x+1)+', row '+(y+1));b.setAttribute('aria-pressed','false');b.onpointerdown=e=>{e.preventDefault();if(variants)return;save();painting={erase:e.button===2||cells.has(conveyorKey(x,y))};stroke(x,y);};b.onpointerenter=()=>{if(painting)stroke(x,y);};b.onclick=e=>{if(e.detail===0&&!variants){save();edit(x,y,cells.has(conveyorKey(x,y)));}};b.oncontextmenu=e=>e.preventDefault();$('grid').append(b);}
const stop=()=>{painting=null;orbit=null;};window.addEventListener('pointerup',stop);window.addEventListener('pointercancel',stop);
const ray=new T.Raycaster(),plane=new T.Plane(new T.Vector3(0,1,0),0),hit=new T.Vector3();function floorPoint(e){const r=renderer.domElement.getBoundingClientRect();ray.setFromCamera(new T.Vector2((e.clientX-r.left)/r.width*2-1,1-(e.clientY-r.top)/r.height*2),camera);return ray.ray.intersectPlane(plane,hit)?[Math.floor(hit.x+4.5),Math.floor(hit.z+4.5)]:null;}
renderer.domElement.onpointerdown=e=>{renderer.domElement.setPointerCapture(e.pointerId);if($('tool').value==='orbit'){orbit=[e.clientX,e.clientY];return;}if(variants)return;save();painting={erase:$('tool').value==='erase'||e.button===2};const p=floorPoint(e);if(p)stroke(...p);};renderer.domElement.onpointermove=e=>{if(orbit){az-=(e.clientX-orbit[0])*.008;el=T.MathUtils.clamp(el+(e.clientY-orbit[1])*.006,.2,1.4);orbit=[e.clientX,e.clientY];render();}else if(painting){const p=floorPoint(e);if(p)stroke(...p);}};renderer.domElement.oncontextmenu=e=>e.preventDefault();
$('preset').onchange=()=>preset($('preset').value);$('clear').onclick=()=>{$('preset').value='empty';preset('empty');};$('undo').onclick=()=>{const prev=history.pop();if(!prev)return;cells=new Set(prev.cells);variants=prev.variants;$('preset').value=prev.preset;currentPreset=prev.preset;rebuild();};$('scale').onchange=render;$('wire').onchange=()=>{library.setWireframe($('wire').checked);render();};$('reset').onclick=()=>{az=Math.PI/4;el=.65;render();};preset('route',false);const observer=new ResizeObserver(render);observer.observe($('stage'));
window.conveyorWorkshop={ready:true,library,models,renderer,camera,cells:()=>new Set(cells),edit(x,y,erase=false){save();edit(x,y,erase);},preset(name){$('preset').value=name;preset(name);},view(a,e){az=a;el=e;render();},masks:()=>[...roots].map(([key,r])=>({key,mask:r.userData.mask,kind:r.userData.kind})),diagnostics:()=>({...library.stats(),gpu:{...renderer.info.memory}})};
window.addEventListener('pagehide',()=>{observer.disconnect();window.removeEventListener('pointerup',stop);window.removeEventListener('pointercancel',stop);library.dispose();cargo.dispose();steel.dispose();ground.geometry.dispose();ground.material.dispose();grid.geometry.dispose();grid.material.dispose();renderer.dispose();},{once:true});
}start().catch(e=>{$('error').textContent=e.message;console.error(e);});
